function accepts(rule, value) {
  if (rule === undefined) return true; // free position (test-side only)
  switch (rule.type) {
    case 'string': return typeof value === 'string';
    case 'boolean': return typeof value === 'boolean';
    case 'null': return value === null;
    case 'number': return typeof value === 'number' && Number.isFinite(value);
    case 'integer': return Number.isInteger(value);
    case 'array': return Array.isArray(value) && value.every(v => accepts(rule.items, v));
    case 'object': {
      if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
      const fields = rule.fields ?? {};
      const ap = rule.additionalProperties === true;
      for (const [name, fr] of Object.entries(fields)) {
        const has = Object.prototype.hasOwnProperty.call(value, name);
        if (!has) { if (fr.required === true) return false; }
        else if (!accepts(fr, value[name])) return false;
      }
      if (!ap) for (const k of Object.keys(value)) if (!(k in fields... hasOwn)) return false;
      return true;
    }
  }
}
```
