export interface RunResult { code: number | null; stdout: string; stderr: string; timedOut: boolean; }

export function runProcess(args: string[], timeoutMs = 20000): Promise<RunResult> {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '', stderr = '';
    child.stdout.setEncoding('utf8'); ...
    const timer = setTimeout(() => { timedOut = true; child.kill('SIGKILL'); }, timeoutMs);
    child.on('error', reject);
    child.on('close', (code) => { clearTimeout(timer); resolve({code, stdout, stderr, timedOut}); });
  });
}

export function runCompare(oldFile, newFile, timeoutMs=20000) {
  return runProcess([APP_PATH, 'compare', '--old', oldFile, '--new', newFile], timeoutMs);
}
