export interface RunningService { child: ChildProcess; port: number; close(): Promise<void>; }

export async function startService(configFile: string, timeoutMs = 20000): Promise<RunningService> {
  const child = spawn(process.execPath, [APP_PATH, 'serve', '--config', configFile, '--port', '0'], {stdio:['ignore','pipe','pipe']});
  let stdout = '';
  const port = await new Promise<number>((resolve, reject) => {
    const timer = setTimeout(() => { child.kill('SIGKILL'); reject(new Error('服务启动超时')); }, timeoutMs);
    child.stdout.setEncoding('utf8');
    child.stdout.on('data', (chunk) => {
      stdout += chunk;
      const m = stdout.match(/listening on http:\/\/127\.0\.0\.1:(\d+)/);
      if (m) { clearTimeout(timer); resolve(Number(m[1])); }
    });
    child.stderr.on('data', ...) // collect for error message
    child.on('exit', (code) => { clearTimeout(timer); reject(new Error(`服务提前退出 code=${code}: ${stdout}`)); });
  });
  return { child, port, async close() { child.kill('SIGTERM'); await once exit or timeout → SIGKILL } };
}
```

