export interface ExampleRequest { method: string; path: string; headers: Record<string,string>; body: string; }
export function sendRequest(port: number, ex: ExampleRequest, timeoutMs = 10000): Promise<{status: number; headers: http.IncomingHttpHeaders; body: string}> {
  return new Promise((resolve, reject) => {
    const req = http.request({ host: '127.0.0.1', port, path: ex.path, method: ex.method, headers: ex.headers }, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', c => body += c);
      res.on('end', () => resolve({status: res.statusCode, headers: res.headers, body}));
    });
    req.setTimeout(timeoutMs, () => { req.destroy(new Error('请求超时')); });
    req.on('error', reject);
    if (ex.body) req.write(ex.body);
    req.end();
  });
}
```

