export type RuleJson = any; // JSON rule object from config

const SCALAR_VALUES: unknown[] = ['s', 0, 0.5, true, null];

export function accepts(rule: RuleJson | undefined, value: unknown): boolean { ... }

export function pairDomain(a: RuleJson | undefined, b: RuleJson | undefined): unknown[] {
  const out: unknown[] = [];
  const seen = new Set<string>();
  const add = (v: unknown) => {
    const key = JSON.stringify(v) ?? 'undefined';
    if (!seen.has(key)) { seen.add(key); out.push(v); }
  };
  for (const s of SCALAR_VALUES) add(s);
  const aObj = a?.type === 'object', bObj = b?.type === 'object';
  const aArr = a?.type === 'array', bArr = b?.type === 'array';
  if (aObj || bObj) {
    add([]); add([0]); // 非对象形状
    const names = new Set<string>();
    for (const r of [a, b]) if (r?.type === 'object' && r.fields) for (const n of Object.keys(r.fields)) names.add(n);
    // 每个字段：缺省 或 取字段对域中的值
    const fieldDomains = [...names].map((name) => ({
      name,
      values: pairDomain(a?.type === 'object' ? a.fields?.[name] : undefined,
                         b?.type === 'object' ? b.fields?.[name] : undefined),
    }));
    // 额外未声明字段：缺席 / 0 / "s"
    const extraOptions = [ABSENT, 0, 's'];
    // 笛卡尔积（带确定性截断上限）
    ...
  }
  if (aArr || bArr) {
    add({}); // 非数组形状
    add([]); // 空数组
    const elemDomain = pairDomain(a?.type==='array' ? a.items : undefined, b?.type==='array' ? b.items : undefined);
    for (const v of elemDomain) add([v]);
  }
  return out;
}
```

