// 运行子进程并收集输出；超过 timeoutMs 仍未退出则 SIGKILL 并标记 timedOut，
// 保证“比较或服务卡住”会在有限时间内表现为测试失败，而不是挂起整个测试进程。
export function runProcess(args: readonly string[], timeoutMs = PROCESS_TIMEOUT_MS): Promise<RunResult> {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '';
    let stderr = '';
    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      child.kill('SIGKILL');
    }, timeoutMs);
    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');
    child.stdout.on('data', (c) => { stdout += c; });
    child.stderr.on('data', (c) => { stderr += c; });
    child.on('error', (e) => { clearTimeout(timer); reject(e); });
    child.on('close', (code) => {
      clearTimeout(timer);
      resolve({ code, stdout, stderr, timedOut });
    });
  });
}

export function runCompare(oldFile: string, newFile: string, timeoutMs = PROCESS_TIMEOUT_MS) {
  return runProcess([APP_PATH, 'compare', '--old', oldFile, '--new', newFile], timeoutMs);
}
