export async function startService(configFile: string, timeoutMs = PROCESS_TIMEOUT_MS): Promise<RunningService> {
  const child = spawn(process.execPath, [APP_PATH, 'serve', '--config', configFile, '--port', '0'], { stdio: ['ignore', 'pipe', 'pipe'] });
  let stdout = '';
  let stderr = '';
