  const port = await new Promise<number>((resolve, reject) => {
    const timer = setTimeout(() => {
      if (!settled) { settled = true; child.kill('SIGKILL'); reject(new Error(`服务启动超时（${timeoutMs}ms）：${stdout}${stderr}`)); }
    }, timeoutMs);
    child.stdout.on('data', (c: string) => {
      stdout += c;
      const m = stdout.match(/listening on http:\/\/127\.0\.0\.1:(\d+)/);
      if (m && !settled) { settled = true; clearTimeout(timer); resolve(Number(m[1])); }
    });
    child.stderr.on('data', (c: string) => { stderr += c; });
    child.on('exit', (code) => {
      if (!settled) { settled = true; clearTimeout(timer); reject(new Error(`服务在就绪前退出（code=${code}）：${stdout}${stderr}`)); }
    });
  });
  const close = async () => {
    if (child.exitCode !== null || child.signalCode !== null) return;
    child.kill('SIGTERM');
    const killer = setTimeout(() => child.kill('SIGKILL'), 5000);
    try { await once(child, 'exit'); } finally { clearTimeout(killer); }
  };
  return { port, close };
}
