// ---- 有限代表值域 ----
const SCALAR_VALUES: readonly unknown[] = ['s', 0, 0.5, true, null];
const MAX_OBJECT_COMBOS = 1000;

export function pairDomain(a: RuleJson | undefined, b: RuleJson | undefined): unknown[] {
  const out: unknown[] = [];
  const seen = new Set<string>();
  const add = (v: unknown): void => {
    const key = JSON.stringify(v) ?? '<unserializable>';
    if (!seen.has(key)) { seen.add(key); out.push(v); }
  };
  // 标量代表值：区分 string / 整数 / 非整数 / boolean / null，
  // 对任何标量规则都同时提供被接受与被拒绝的取值。
  for (const s of SCALAR_VALUES) add(s);

  const aObj = a?.type === 'object';
  const bObj = b?.type === 'object';
  const aArr = a?.type === 'array';
  const bArr = b?.type === 'array';

  if (aObj || bObj) {
    add([]);      // 非对象形状：数组
    const names = new Set<string>();
    for (const r of [a, b]) {
      if (r?.type === 'object' && r.fields) {
        for (const n of Object.keys(r.fields)) names.add(n);
      }
    }
    const fieldDomains = [...names].map((name) => ({
      name,
      values: pairDomain(
        aObj ? a?.fields?.[name] : undefined,
        bObj ? b?.fields?.[name] : undefined,
      ),
    }));
    // 每个声明字段：缺省 或 取字段对域中的每个值（字段缺失与 null 都被覆盖，
    // 因为 null 在标量代表值中）；再叠加一个双方都未声明的额外字段
    // （缺省 / 0 / "s"），用于区分 additionalProperties 两种策略。
    const ABSENT = Symbol('absent');
    ...cartesian...
  }
  if (aArr || bArr) {
    add({});   // 非数组形状：对象
    add([]);   // 空数组
    const elemDomain = pairDomain(aArr ? a?.items : undefined, bArr ? b?.items : undefined);
    for (const v of elemDomain) add([v]);  // 非空数组：逐元素代表值
  }
  return out;
}
