        assert.ok(ep.reasons.length > 0, `${label}：至少一处原因`);
        for (const reason of ep.reasons) {
          assert.equal(
            Object.prototype.hasOwnProperty.call(reason, 'pointer'),
            false,
            `${label}：接口级原因不得携带 pointer`,
